            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching intervals in result
    if not result:
        return []

    result_sorted = sorted(result)
    final = [result_sorted[0]]
    for start, end in result_sorted[1:]:
        if start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

